// Local-only test fixtures (raw factory tables and golden images built by the Python tools). They are
// generated by tools/export_data.py from a firmware dump and are not published, so the tests that need
// them are skipped on a public checkout.
import { test } from 'node:test';
import { existsSync, readFileSync } from 'node:fs';
import * as core from '../ma3-core.js';

const dir = new URL('../test/fixtures/', import.meta.url);
const read = name => JSON.parse(readFileSync(new URL(name, dir), 'utf8'));

export const HAVE_FIXTURES = existsSync(new URL('factory-tables.json', dir)) && existsSync(new URL('golden.json', dir));
export const tables = HAVE_FIXTURES ? read('factory-tables.json') : null;
export const golden = HAVE_FIXTURES ? read('golden.json') : null;

export async function loadTables() {
  if (tables) await core.setFactoryTables(core.hexToBytes(tables.codec), core.hexToBytes(tables.akm));
}

// test() that is skipped when the local fixtures are missing.
export const fixtureTest = (name, fn) =>
  test(name, { skip: HAVE_FIXTURES ? false : 'needs local firmware fixtures (run tools/export_data.py)' }, async t => { await loadTables(); return fn(t); });
